using Application.DTO;
using Application.Mappers.Interfaces;
using Domain.Entities;
using Riok.Mapperly.Abstractions;

namespace Application.Mappers
{
    [Mapper]
    public partial class UserMapper : IUserMapper
    {
        public partial UserDto ToDto(User model);

        // Identity is generated by the service.
        [MapperIgnoreSource(nameof(UserDto.Id))]
        [MapperIgnoreTarget(nameof(User.Id))]
        public partial User ToModel(UserDto dto);

        [MapperIgnoreSource(nameof(UserDto.Id))]
        [MapperIgnoreTarget(nameof(User.Id))]
        public partial void ApplyTo(UserDto dto, [MappingTarget] User model);
    }
}
